**🚨 suggestion (security):** Redaction currently skips nested arrays, which may still leak sensitive data.

Because arrays are copied as-is, any sensitive fields inside objects within arrays (e.g. `[{ apiKey: '...' }]`) will still be logged. Consider recursing into arrays (e.g. map elements and redact any nested objects) so secrets are consistently redacted regardless of structure.

```suggestion
/** Redact sensitive keys from objects before logging. */
const SENSITIVE_KEYS = /apikey|password|secret|token|authorization|connectionstring/i;

function redact(obj: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    if (SENSITIVE_KEYS.test(k)) {
      out[k] = "[REDACTED]";
    } else if (Array.isArray(v)) {
      out[k] = v.map((item) => {
        if (item && typeof item === "object" && !Array.isArray(item)) {
          return redact(item as Record<string, unknown>);
        }
        return item;
      });
    } else if (v && typeof v === "object") {
      out[k] = redact(v as Record<string, unknown>);
    } else {
      out[k] = v;
    }
  }
  return out;
}
